For a responsive translation endpoint, use this flow: **validate → check Redis → call DeepL on a cache miss → cache the result → respond**. Keep the DeepL key on the server, set a request timeout, and let translation continue if Redis is unavailable.

```js
const express = require('express');
const axios = require('axios');
const { createClient } = require('redis');
const crypto = require('node:crypto');

const app = express();
app.use(express.json({ limit: '32kb' }));

const redis = createClient({ url: process.env.REDIS_URL });
redis.on('error', (err) => console.error('Redis error:', err));
redis.connect().catch((err) => console.error('Redis connection failed:', err));

const deeplUrl = process.env.DEEPL_API_URL || 'https://api.deepl.com/v2/translate';
// For DeepL API Free, use https://api-free.deepl.com/v2/translate

function cacheKey({ text, sourceLang, targetLang }) {
  // Hash the text so cache keys stay short and don't expose user text in Redis keys.
  const digest = crypto.createHash('sha256').update(text).digest('hex');
  return `translation:v1:${sourceLang || 'auto'}:${targetLang}:${digest}`;
}

app.post('/api/translate', async (req, res, next) => {
  const { text, sourceLang, targetLang } = req.body ?? {};

  if (typeof text !== 'string' || !text.trim() ||
      typeof targetLang !== 'string' || !targetLang.trim()) {
    return res.status(400).json({
      error: 'text and targetLang are required',
    });
  }

  const input = {
    text: text.trim(),
    sourceLang: sourceLang?.trim().toUpperCase(),
    targetLang: targetLang.trim().toUpperCase(),
  };
  const key = cacheKey(input);

  try {
    // Cache is an optimization, not a dependency: continue if Redis is down.
    try {
      const cached = await redis.get(key);
      if (cached !== null) {
        return res.json({ translatedText: cached, cache: 'hit' });
      }
    } catch (err) {
      console.warn('Redis read failed; continuing without cache:', err.message);
    }

    const payload = {
      text: [input.text],
      target_lang: input.targetLang,
      ...(input.sourceLang && { source_lang: input.sourceLang }),
    };

    const response = await axios.post(deeplUrl, payload, {
      headers: {
        Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
        'Content-Type': 'application/json',
      },
      timeout: 2500, // Choose this based on your service's latency budget.
    });

    const translatedText = response.data?.translations?.[0]?.text;
    if (typeof translatedText !== 'string') {
      throw new Error('Unexpected response from translation provider');
    }

    try {
      await redis.set(key, translatedText, { EX: 1200 }); // 20-minute TTL
    } catch (err) {
      console.warn('Redis write failed:', err.message);
    }

    return res.json({ translatedText, cache: 'miss' });
  } catch (err) {
    next(err);
  }
});

// Express error handler
app.use((err, req, res, next) => {
  console.error('Translation request failed:', err.message);

  if (err.code === 'ECONNABORTED') {
    return res.status(504).json({ error: 'Translation provider timed out' });
  }

  const status = err.response?.status;
  if (status === 429) {
    return res.status(503).json({ error: 'Translation service is temporarily busy' });
  }

  res.status(502).json({ error: 'Translation service is unavailable' });
});

app.listen(4500, () => console.log('Translation service listening on port 4500'));
```

A few important details:

- Include **source language, target language, and text** in the cache identity. If you add options such as formality or glossary IDs, include those too.
- DeepL accepts multiple texts in one request. If your app translates several independent strings together, send them in a single `text: [...]` request instead of making one HTTP call per string.
- Avoid retrying every failed request immediately: retries increase latency and can amplify rate limits. If you add retries, restrict them to transient failures such as `429` or `5xx`, use a small attempt limit with jitter, and honor `Retry-After` when present.
- Measure cache-hit and cache-miss latency separately (ideally p50/p95 as well as average). With an 85% cache hit rate, the remaining misses may dominate the overall response time.
- If the chatbot can proceed without translation, return the original text as a deliberate fallback or handle the translation failure in the chatbot; don’t silently treat a failed translation as a successful one.

